def shapes(grid):
    """Extract each connected 3x3 cross shape's color bounding box, left to right."""
    h,w=len(grid),len(grid[0])
    seen=[[False]*w for _ in range(h)]; out=[]
    for i in range(h):
        for j in range(w):
            if grid[i][j] and not seen[i][j]:
                stack=[(i,j)]; cells=[]
                while stack:
                    a,b=stack.pop()
                    if seen[a][b]: continue
                    seen[a][b]=True; cells.append((a,b))
                    for da in(-1,0,1):
                        for db in(-1,0,1):
                            na,nb=a+da,b+db
                            if 0<=na<h and 0<=nb<w and grid[na][nb] and not seen[na][nb]:
                                stack.append((na,nb))
                r0=min(a for a,b in cells); c0=min(b for a,b in cells)
                r1=max(a for a,b in cells); c1=max(b for a,b in cells)
                out.append([row[c0:c1+1] for row in grid[r0:r1+1]])
    out.sort(key=lambda s:(s[1][1]))  # by left column of original? need order left-to-right
    return out
def hstack(grids):
    """Concatenate grids horizontally."""
    return [sum((g[i] for g in grids),[]) for i in range(max(len(g) for g in grids))]
def transform(grid):
    sh=shapes(grid)
    sh.sort(key=lambda s: s[1][1])
    return hstack(sh)
